<script setup>
import { computed, reactive, ref } from 'vue'
const key = 'tutorias-perfil-v1'
const empty = { nombre:'', apellido:'', email:'', telefono:'', institucion:'', carrera:'', materia:'', ciudad:'', acercaDe:'', modalidad:'Presencial' }
let stored = {}
try { stored = JSON.parse(localStorage.getItem(key) || '{}') } catch {}
const profile = reactive({ ...empty, ...stored })
const editing = ref(false)
const notice = ref('')
const name = computed(() => [profile.nombre, profile.apellido].filter(Boolean).join(' ') || 'Tu nombre')
const initials = computed(() => ((profile.nombre[0] || 'P') + (profile.apellido[0] || '')).toUpperCase())
const filled = computed(() => ['nombre','apellido','email','telefono','institucion','carrera','materia','ciudad','acercaDe'].filter(k => profile[k].trim()).length)
function save() { localStorage.setItem(key, JSON.stringify(profile)); editing.value = false; notice.value = 'Tus cambios se guardaron en este dispositivo.'; setTimeout(() => notice.value = '', 3500) }
function cancel() { Object.assign(profile, empty, JSON.parse(localStorage.getItem(key) || '{}')); editing.value = false }
</script>
<template>
<main class="profile-page"><div class="profile-wrap">
<div class="eyebrow"><i></i> CUENTA PERSONAL</div>
<div class="heading"><div><h1>Mi perfil</h1><p>Tu espacio para contar quién sos y cómo acompañás el aprendizaje.</p></div><button v-if="!editing" class="edit" @click="editing=true">✎ &nbsp;Editar perfil</button></div>
<section class="hero"><div class="avatar">{{ initials }}</div><div class="hero-copy"><small>{{ profile.materia || 'COMUNIDAD DE TUTORÍAS' }}</small><h2>{{ name }}</h2><p>{{ profile.institucion || 'Completa tu perfil para presentarte a la comunidad' }}<span v-if="profile.ciudad"> · {{ profile.ciudad }}</span></p></div><div class="progress"><div><span>Tu perfil</span><b>{{ Math.round(filled/9*100) }}%</b></div><i><span :style="{width: Math.round(filled/9*100) + '%'}"></span></i><small>{{ filled }} de 9 datos completados</small></div></section>
<div v-if="notice" class="notice">✓ &nbsp;{{ notice }}</div>
<div class="grid"><section class="card about"><div class="card-title"><div><small>PRESENTACIÓN</small><h3>Sobre mí</h3></div><b>✦</b></div><p v-if="!editing" class="about-text">{{ profile.acercaDe || 'Este es tu lugar para compartir tu experiencia, tus intereses y aquello que te entusiasma de enseñar. Agregá una breve presentación para que otros puedan conocerte.' }}</p><label v-else class="field">Una breve presentación<textarea v-model="profile.acercaDe" rows="5" maxlength="500" placeholder="Contá qué enseñás y qué te gusta de acompañar a tus estudiantes…"></textarea><small>{{ profile.acercaDe.length }}/500 caracteres</small></label><div class="about-foot">✦ &nbsp;Aprender juntos hace la diferencia</div></section>
<section class="card details"><div class="card-title"><div><small>TU INFORMACIÓN</small><h3>Datos personales</h3></div><b>⌘</b></div><div class="fields">
<label class="field">Nombre<input v-if="editing" v-model="profile.nombre" autocomplete="given-name" placeholder="Tu nombre"><strong v-else>{{ profile.nombre || 'Sin completar' }}</strong></label>
<label class="field">Apellido<input v-if="editing" v-model="profile.apellido" autocomplete="family-name" placeholder="Tu apellido"><strong v-else>{{ profile.apellido || 'Sin completar' }}</strong></label>
<label class="field">Correo electrónico<input v-if="editing" v-model="profile.email" type="email" autocomplete="email" placeholder="nombre@correo.com"><strong v-else>{{ profile.email || 'Sin completar' }}</strong></label>
<label class="field">Teléfono<input v-if="editing" v-model="profile.telefono" type="tel" autocomplete="tel" placeholder="+54 11 1234 5678"><strong v-else>{{ profile.telefono || 'Sin completar' }}</strong></label>
<label class="field">Institución<input v-if="editing" v-model="profile.institucion" placeholder="Institución o universidad"><strong v-else>{{ profile.institucion || 'Sin completar' }}</strong></label>
<label class="field">Carrera o área<input v-if="editing" v-model="profile.carrera" placeholder="Ej. Ciencias de la educación"><strong v-else>{{ profile.carrera || 'Sin completar' }}</strong></label>
<label class="field">Materia principal<input v-if="editing" v-model="profile.materia" placeholder="Ej. Matemática"><strong v-else>{{ profile.materia || 'Sin completar' }}</strong></label>
<label class="field">Ciudad<input v-if="editing" v-model="profile.ciudad" autocomplete="address-level2" placeholder="Tu ciudad"><strong v-else>{{ profile.ciudad || 'Sin completar' }}</strong></label>
<label class="field">Modalidad preferida<select v-if="editing" v-model="profile.modalidad"><option>Presencial</option><option>Virtual</option><option>Híbrida</option></select><strong v-else>{{ profile.modalidad }}</strong></label></div>
<div v-if="editing" class="actions"><small class="privacy">Tus datos se guardan de forma privada en este navegador.</small><button class="cancel" @click="cancel">Cancelar</button><button class="save" @click="save">Guardar cambios &nbsp;→</button></div><p v-else class="privacy read-only">Tus datos se guardan en este navegador y podés actualizarlos cuando quieras.</p></section>
<aside class="tip"><b>✦</b><div><small>UN CONSEJO</small><h3>Un perfil completo genera confianza</h3><p>Sumá tus datos y una presentación breve para que estudiantes y tutores sepan más de vos.</p><button v-if="!editing" @click="editing=true">Completar mi perfil &nbsp;→</button></div></aside></div></div></main>
</template>
